#include <zephyr/ztest.h>
#include <zephyr/device.h>
#include <zephyr/drivers/eeprom.h>
#include <string.h>

#define EEPROM_NODE DT_ALIAS(eeprom0)

#if !DT_NODE_HAS_STATUS(EEPROM_NODE, okay)
#error "No EEPROM device found in DT"
#endif

static const struct device *eeprom_dev = DEVICE_DT_GET(EEPROM_NODE);

static void test_eeprom_init(void)
{
    zassert_true(device_is_ready(eeprom_dev), "EEPROM device is not ready");
}

static void test_out_of_bounds(void)
{
    uint8_t write_buf[16];
    uint8_t read_buf[16];
    size_t eeprom_size;
    int ret;

    zassert_true(eeprom_dev != NULL, "EEPROM device pointer is NULL");

    eeprom_size = eeprom_get_size(eeprom_dev);
    zassert_true(eeprom_size > 0, "EEPROM size must be greater than 0 for out-of-bounds tests");

    /* Scenario 1: Write starting exactly at EEPROM_SIZE (offset is out of bounds) */
    ret = eeprom_write(eeprom_dev, eeprom_size, write_buf, sizeof(write_buf));
    zassert_true(ret < 0, "Write at offset == size should fail");

    /* Scenario 2: Read starting exactly at EEPROM_SIZE (offset is out of bounds) */
    ret = eeprom_read(eeprom_dev, eeprom_size, read_buf, sizeof(read_buf));
    zassert_true(ret < 0, "Read at offset == size should fail");

    /* Scenario 3: Write with offset + length exceeding EEPROM_SIZE */
    /* Attempt to write 2 bytes: 1 at size-1, 1 at size (out of bounds) */
    ret = eeprom_write(eeprom_dev, eeprom_size - 1, write_buf, 2);
    zassert_true(ret < 0, "Write with offset + length > size should fail");

    /* Scenario 4: Read with offset + length exceeding EEPROM_SIZE */
    /* Attempt to read 2 bytes: 1 at size-1, 1 at size (out of bounds) */
    ret = eeprom_read(eeprom_dev, eeprom_size - 1, read_buf, 2);
    zassert_true(ret < 0, "Read with offset + length > size should fail");

    /* Scenario 5: Write with very large offset, but small length */
    /* This tests if the driver handles large, clearly out-of-bounds offsets */
    ret = eeprom_write(eeprom_dev, eeprom_size + 100, write_buf, 1);
    zassert_true(ret < 0, "Write with large out-of-bounds offset should fail");

    /* Scenario 6: Read with very large offset, but small length */
    ret = eeprom_read(eeprom_dev, eeprom_size + 100, read_buf, 1);
    zassert_true(ret < 0, "Read with large out-of-bounds offset should fail");

    /* Scenario 7: Write with offset 0 and length exceeding EEPROM_SIZE */
    ret = eeprom_write(eeprom_dev, 0, write_buf, eeprom_size + 1);
    zassert_true(ret < 0, "Write with length > size should fail");

    /* Scenario 8: Read with offset 0 and length exceeding EEPROM_SIZE */
    ret = eeprom_read(eeprom_dev, 0, read_buf, eeprom_size + 1);
    zassert_true(ret < 0, "Read with length > size should fail");
}

ZTEST_SUITE(eeprom, NULL, NULL, NULL, NULL, NULL);

ZTEST_USER(eeprom, test_eeprom_init);
ZTEST_USER(eeprom, test_out_of_bounds);
